INSERT INTO content_blocks (page,slot,kind,body,position,state,updated_at) VALUES ('book-an-appointment','main','hero','{"lead": "SAFE HARBOURS", "heading": "Give a Traumatized Child the Safety, Love, and Future They Deserve", "intro": "<p>Right now, there are children in Ontario who have nowhere safe to go. They’ve faced trauma, addiction, even exploitation, and they urgently need homes where they can feel protected, supported, and loved. Safe Harbours equips everyday people like you with the training, support, and resources to make that possible. If you’ve ever felt called to make a real difference, this is your chance.</p><p><a class=\"button\" href=\"#book\">Book a Consultation</a></p>", "bg": "image-set(url(''/assets/uploads/2025/10/eab76d9f553da936be9cfefd6ce5cef1c9a6d7db-scaled-1920.avif'') type(''image/avif''), url(''/assets/uploads/2025/10/eab76d9f553da936be9cfefd6ce5cef1c9a6d7db-scaled-1920.webp'') type(''image/webp''), url(''/assets/uploads/2025/10/eab76d9f553da936be9cfefd6ce5cef1c9a6d7db-scaled.jpg''))", "variant": "booking-hero"}',0,'published','');
INSERT INTO content_blocks (page,slot,kind,body,position,state,updated_at) VALUES ('book-an-appointment','main','eventSection','{"eyebrow": "Start Here. ", "heading": "Book a call with Chris!", "body": "<p>Reserve time with Safe Harbours’ very own Parent Experience Coordinator, to answer any introductory questions you may have. You won’t be on this journey alone. We offer training, education, and counselling support along the way.</p>", "calendlyUrl": "https://calendly.com/christopher-wilson-safeharbours/fosterering-q-a?hide_event_type_details=1&hide_gdpr_banner=1", "bg": "image-set(url(''/assets/uploads/2025/10/sdds-scaled-1920.avif'') type(''image/avif''), url(''/assets/uploads/2025/10/sdds-scaled-1920.webp'') type(''image/webp''), url(''/assets/uploads/2025/10/sdds-scaled.jpg''))"}',1,'published','');
INSERT INTO content_blocks (page,slot,kind,body,position,state,updated_at) VALUES ('book-an-appointment','main','steps','{"heading": "", "steps": [{"reverse": false, "heading": "Why Should You Foster A Child?", "body": "<p>Every day in Ontario, children are removed from unsafe environments because of abuse, neglect, trauma, or exploitation. Many of these kids have nowhere safe to go, and without the right foster homes, they risk falling deeper into cycles of pain, addiction, and instability. Fostering gives them something they’ve lost: hope, stability, and a chance to heal.</p><p>We equip you with specialized training, 24/7 support, and a community of care, so you’ll never feel like you’re doing this alone.<br>When you foster, you don’t just change one child’s life; you change their future.</p>", "img": {"avif": "/assets/uploads/2025/10/Frame-34158-640.avif 640w", "webp": "/assets/uploads/2025/10/Frame-34158-640.webp 640w", "jpg": "/assets/uploads/2025/10/Frame-34158.png", "w": 834, "h": 807}}, {"reverse": false, "heading": "How To Become A Foster Parent", "body": "<p>Getting started is simple. It begins with a friendly home visit and a short application, including background and safety checks. From there, we guide you through a home study to ensure the right fit and provide specialized trauma-focused training so you feel fully prepared and confident. Safe Harbours makes every step clear and supportive, so you can focus on what matters most: giving a child a safe, loving home.</p><p><a class=\"button\" href=\"#book\">Book a Consultation</a></p>", "img": {"avif": "/assets/uploads/2025/10/Frame-3412-640.avif 640w", "webp": "/assets/uploads/2025/10/Frame-3412-640.webp 640w", "jpg": "/assets/uploads/2025/10/Frame-3412.png", "w": 834, "h": 696}}], "sectionClass": "lp-section"}',2,'published','');
INSERT INTO content_blocks (page,slot,kind,body,position,state,updated_at) VALUES ('book-an-appointment','main','valueCards','{"heading": "Why Choose Safe Harbours", "cards": [{"img": {"avif": "/assets/uploads/2024/10/house-icon-e1729732863639-147.avif 147w", "webp": "/assets/uploads/2024/10/house-icon-e1729732863639-147.webp 147w", "jpg": "/assets/uploads/2024/10/house-icon.png", "w": 147, "h": 134}, "title": "Specialized Trauma Training", "text": "<p>Learn evidence-based strategies to care for children with exceptional needs.</p>", "style": "navy"}, {"img": {"avif": "/assets/uploads/2024/10/heart-people-2-132.avif 132w", "webp": "/assets/uploads/2024/10/heart-people-2-132.webp 132w", "jpg": "/assets/uploads/2024/10/heart-people-2.png", "w": 132, "h": 132}, "title": "Premium Compensation", "text": "<p>Receive a higher per diem that reflects the added time and commitment.</p>", "style": "pink"}, {"img": {"avif": "/assets/uploads/2024/10/hands-light-icon-146.avif 146w", "webp": "/assets/uploads/2024/10/hands-light-icon-146.webp 146w", "jpg": "/assets/uploads/2024/10/hands-light-icon.png", "w": 146, "h": 136}, "title": "24/7 Professional Support", "text": "<p>Round-the-clock access to staff, resources, and emergency help.</p>", "style": "navy"}, {"img": {"avif": "/assets/uploads/2024/10/famly-icon-146.avif 146w", "webp": "/assets/uploads/2024/10/famly-icon-146.webp 146w", "jpg": "/assets/uploads/2024/10/famly-icon.png", "w": 146, "h": 136}, "title": "Ongoing Staffing Help", "text": "<p>Additional support staff are available when a child’s needs require it.</p>", "style": "lightpink"}, {"img": {"avif": "/assets/uploads/2024/10/heart-people-142.avif 142w", "webp": "/assets/uploads/2024/10/heart-people-142.webp 142w", "jpg": "/assets/uploads/2024/10/heart-people.png", "w": 142, "h": 142}, "title": "Lasting Transformation", "text": "<p>Your role creates hope, stability, and a path to healing for youth who need it most.</p>", "style": "navy"}]}',3,'published','');
INSERT INTO content_blocks (page,slot,kind,body,position,state,updated_at) VALUES ('book-an-appointment','main','testimonials','{"items": [{"quote": "“Safe Harbours provided me with the support and training I needed to become a successful foster parent. I highly recommend their services.”", "author": "Carly T", "role": "Foster Parent"}, {"quote": "“I can''t thank Safe Harbours enough for the care and support they provided for my foster child. They truly made a difference in his life.”", "author": "Ziya C", "role": "Foster Parent"}, {"quote": "“Safe Harbours is an amazing organization. They provide quality care and services for foster children and families alike.”", "author": "Sarah J", "role": "Foster Parent"}]}',4,'published','');
INSERT INTO content_blocks (page,slot,kind,body,position,state,updated_at) VALUES ('book-an-appointment','main','contactHero','{"heading": "Contact Us today", "description": "<p>Have questions about fostering with Safe Harbours?  Our team is here to answer them. Reach out to us and we will get back to you as soon as we can.</p>", "variant": "contact-hero", "showImage": false, "bg": "image-set(url(''/assets/uploads/2024/10/Hero-ContactUs-scaled-1920.avif'') type(''image/avif''), url(''/assets/uploads/2024/10/Hero-ContactUs-scaled-1920.webp'') type(''image/webp''), url(''/assets/uploads/2024/10/Hero-ContactUs-scaled.jpg''))"}',5,'published','');
